/// 怪獣の定義 (`@HmonsterName` ほか)
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct MonsterSpec {
    pub name: &'static str,
    /// 最低体力 (`@HmonsterBHP`)
    pub base_hp: i64,
    /// 体力の幅 (`@HmonsterDHP`)
    pub hp_range: i64,
    /// 特殊能力 (`@HmonsterSpecial`)
    pub special: i64,
    /// 経験値 (`@HmonsterExp`)
    pub exp: i64,
    /// 死体の値段 (`@HmonsterValue`)
    pub value: i64,
    pub image: &'static str,
    /// 硬化中の画像 (`@HmonsterImage2`)。空文字列なら無し
    pub image_hardened: &'static str,
}

